(4726510, 682106, 19708, '<td valign="top">I really love the way each stand (gas pumps??) ar elit on top.<br/>Great point of view here.</td>', 'I really love the way each stand (gas pumps??) ar elit on top.Great point of view here.', '2008-05-26 23:40:28.000000', NULL, 1),
(4726512, 681511, 19708, '<td valign="top">Unusual point of view on this. Crisp, clean and works well.</td>', 'Unusual point of view on this. Crisp, clean and works well.', '2008-05-26 23:41:55.000000', NULL, 1),
(4726517, 682186, 91496, '<td valign="top">Very nice.  It is a little snap-shot like in composition, but I imagine they were pretty fair away.  Lovely blues.</td>', 'Very nice.  It is a little snap-shot like in composition, but I imagine they were pretty fair away.  Lovely blues.', '2008-05-26 23:43:37.000000', NULL, 1),
(4726521, 682075, 91496, '<td valign="top">Very nice.  The texture is great.  The leading lines lead me right to the ominous sky.  I can smell the salt air in this one.  Bravo!</td>', 'Very nice.  The texture is great.  The leading lines lead me right to the ominous sky.  I can smell the salt air in this one.  Bravo!', '2008-05-26 23:45:42.000000', NULL, 1),
(4726526, 681282, 19708, '<td valign="top">The overall colors here seem odd - especially the yellow clouds. Not sure what to make of that, as the red &amp; white on the flag is right.</td>', 'The overall colors here seem odd - especially the yellow clouds. Not sure what to make of that, as the red & white on the flag is right.', '2008-05-26 23:47:24.000000', NULL, 1),
(4726530, 681639, 91496, '<td valign="top">Lovely.  A "real" photograph.  Nice exposure to get silouettes of the people.</td>', 'Lovely.  A "real" photograph.  Nice exposure to get silouettes of the people.', '2008-05-26 23:49:14.000000', NULL, 1),
(4726533, 681720, 91496, '<td valign="top">Very nice.  The boat is a little far away to have a major impact, but who cares it is so nice.  A lot of painters would love to paint the scene you have capture.</td>', 'Very nice.  The boat is a little far away to have a major impact, but who cares it is so nice.  A lot of painters would love to paint the scene you have capture.', '2008-05-26 23:51:21.000000', NULL, 1),
(4726538, 681613, 91496, '<td valign="top">Nice reflections.  Not sure B&amp;W was the right choice are there is very little black to offset all the white.</td>', 'Nice reflections.  Not sure B&W was the right choice are there is very little black to offset all the white.', '2008-05-26 23:53:06.000000', NULL, 1),
(4726540, 681511, 91496, '<td valign="top">Lovely colors in the sky and building.  Would not have known this was part of a boat without the challenge name.  Title does not help here either.  Tilt and Border not to my taste.</td>', 'Lovely colors in the sky and building.  Would not have known this was part of a boat without the challenge name.  Title does not help here either.  Tilt and Border not to my taste.', '2008-05-26 23:54:52.000000', NULL, 1),
(4726543, 681986, 91496, '<td valign="top">Nice Chevy.  Odd choice for a boat theme (and I did get the cruising tie in). Cut off ship name and odd man kind of detract from the impact.</td>', 'Nice Chevy.  Odd choice for a boat theme (and I did get the cruising tie in). Cut off ship name and odd man kind of detract from the impact.', '2008-05-26 23:56:53.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4726545, 682131, 91496, '<td valign="top">Great colors and lines.  Tough angle with all the other boats as clutter to detract from your subjects.  I''ll take the sailboat!</td>', 'Great colors and lines.  Tough angle with all the other boats as clutter to detract from your subjects.  I''ll take the sailboat!', '2008-05-26 23:58:36.000000', NULL, 1),
(4726553, 682123, 91496, '<td valign="top">I am doing a love/hate with this one.  Love the siloutee on the man, not so found of the wierd jaggies all around him (they look like a map of some country).</td>', 'I am doing a love/hate with this one.  Love the siloutee on the man, not so found of the wierd jaggies all around him (they look like a map of some country).', '2008-05-27 00:01:41.000000', NULL, 1),
(4726557, 680936, 59148, '<td valign="top">Hey its EJ!! I know that helmet anywhere...</td>', 'Hey its EJ!! I know that helmet anywhere...', '2008-05-27 00:04:52.000000', NULL, 1),
(4726559, 682191, 91496, '<td valign="top">Very nice.  Good POV that does the best yet with a moored vessel, which are really very unphotogenic.</td>', 'Very nice.  Good POV that does the best yet with a moored vessel, which are really very unphotogenic.', '2008-05-27 00:05:56.000000', NULL, 1),
(4726562, 681973, 91496, '<td valign="top">Nice photo.  Not a fan of the border.  I noticed it way before the finer points of the photo.</td>', 'Nice photo.  Not a fan of the border.  I noticed it way before the finer points of the photo.', '2008-05-27 00:06:49.000000', NULL, 1),
(4726565, 682128, 91496, '<td valign="top">Nicely done.  Evoking emotion wiht a folded piece of paper.  Bravo!</td>', 'Nicely done.  Evoking emotion wiht a folded piece of paper.  Bravo!', '2008-05-27 00:08:24.000000', NULL, 1),
(4726571, 681811, 91496, '<td valign="top">Nice idea.  I think the desaturation makes it look more like grafitti than rust and old paint.</td>', 'Nice idea.  I think the desaturation makes it look more like grafitti than rust and old paint.', '2008-05-27 00:11:46.000000', NULL, 1),
(4726576, 681162, 91496, '<td valign="top">Confusing perspective insize between the bird, 2 benches, and the boat.</td>', 'Confusing perspective insize between the bird, 2 benches, and the boat.', '2008-05-27 00:15:09.000000', NULL, 1),
(4726583, 682189, 91496, '<td valign="top">Nice shot.  Very serence mood.</td>', 'Nice shot.  Very serence mood.', '2008-05-27 00:18:58.000000', NULL, 1),
(4726694, 682128, 5746, '<td valign="top">I thought about it as well, but finally didn''t enter. The details inside the boat are blown out. I like the negative space and green colour of water. Maybe if you tried longer exposure, the details wouldl stay. Very nice entry.</td>', 'I thought about it as well, but finally didn''t enter. The details inside the boat are blown out. I like the negative space and green colour of water. Maybe if you tried longer exposure, the details wouldl stay. Very nice entry.', '2008-05-27 02:15:51.000000', NULL, 1),
(4726698, 681811, 9668, '<td valign="top">Interesting use of selective de-saturation.</td>', 'Interesting use of selective de-saturation.', '2008-05-27 02:22:06.000000', NULL, 1),
(4726699, 681733, 9668, '<td valign="top">Awesome backlighting!</td>', 'Awesome backlighting!', '2008-05-27 02:22:39.000000', NULL, 1),
(4726706, 681714, 9668, '<td valign="top">Pelicans in the foreground ar nice. Don''t think the soft focus is necessary.</td>', 'Pelicans in the foreground ar nice. Don''t think the soft focus is necessary.', '2008-05-27 02:29:19.000000', NULL, 1),
(4726708, 682106, 9668, '<td valign="top">nice lighting!</td>', 'nice lighting!', '2008-05-27 02:35:49.000000', NULL, 1),
(4726713, 682031, 9668, '<td valign="top">sweet shot!</td>', 'sweet shot!', '2008-05-27 02:39:20.000000', NULL, 1),
(4726724, 681503, 5746, '<td valign="top">I like calmness of the water here. Nice detail. Very good light (morning?). For such symmetrical picture, fill the frame was good composition choice I guess. It has a "summer feel". Like picture from vacations. Nice try on the challenge theme. When I thought of "boats" I have exactly something like that in my mind. Should score well. Good luck.</td>', 'I like calmness of the water here. Nice detail. Very good light (morning?). For such symmetrical picture, fill the frame was good composition choice I guess. It has a "summer feel". Like picture from vacations. Nice try on the challenge theme. When I thought of "boats" I have exactly something like that in my mind. Should score well. Good luck.', '2008-05-27 02:47:35.000000', NULL, 1),
(4726733, 681400, 73980, '<td valign="top">love that sky!</td>', 'love that sky!', '2008-05-27 03:05:20.000000', NULL, 1),
(4726736, 680438, 73980, '<td valign="top">LOL, too funny...  you actually read the boat names??  :)</td>', 'LOL, too funny...  you actually read the boat names??  :)', '2008-05-27 03:06:24.000000', NULL, 1),
(4726737, 682098, 31948, '<td valign="top">10</td>', '10', '2008-05-27 03:07:10.000000', NULL, 1),
(4726749, 681289, 14867, '<td valign="top">Centered, but harmoniuously composed. The blured foreground adds depth, though it is a bit distracting. Nice light, globally slightly dark.</td>', 'Centered, but harmoniuously composed. The blured foreground adds depth, though it is a bit distracting. Nice light, globally slightly dark.', '2008-05-27 03:20:42.000000', NULL, 1),
(4726752, 681720, 14867, '<td valign="top">To darken the trees and their reflexion was a clever idea to make stand out this very little boat, even if the black area is a bit too dark and/or to big here IMHO.</td>', 'To darken the trees and their reflexion was a clever idea to make stand out this very little boat, even if the black area is a bit too dark and/or to big here IMHO.', '2008-05-27 03:24:27.000000', NULL, 1),
