(4730085, 681160, 30982, '<td valign="top">A nice way to fit a sunset into the shot!  The boat tends to blend a bit, ie doesn''t really stand out nicely as the subject - the rope thingie is the most prominent part of the image to me.  Overall to be very soft in focus and a bit "flat", ie in need of more contrast which looks to be hard to get with this light?</td>', 'A nice way to fit a sunset into the shot!  The boat tends to blend a bit, ie doesn''t really stand out nicely as the subject - the rope thingie is the most prominent part of the image to me.  Overall to be very soft in focus and a bit "flat", ie in need of more contrast which looks to be hard to get with this light?', '2008-05-28 12:56:20.000000', NULL, 1),
(4730086, 682189, 30982, '<td valign="top">Wonderfully calm water for this - the reflection is quite rich in detail.</td>', 'Wonderfully calm water for this - the reflection is quite rich in detail.', '2008-05-28 12:56:41.000000', NULL, 1),
(4730092, 681996, 92874, '<td valign="top">Great use of reflections and lines. Perhaps if the focus was more on the coloured section(boat?) rather than the background (roller door?) the image may have more impact. Just my 2cents worth.</td>', 'Great use of reflections and lines. Perhaps if the focus was more on the coloured section(boat?) rather than the background (roller door?) the image may have more impact. Just my 2cents worth.', '2008-05-28 12:57:47.000000', NULL, 1),
(4730095, 681994, 30982, '<td valign="top">A very nice shot showing the life of "boat people" - those that life on their boats at least part time.  I love the flower boxes on Celine!</td>', 'A very nice shot showing the life of "boat people" - those that life on their boats at least part time.  I love the flower boxes on Celine!', '2008-05-28 13:00:04.000000', NULL, 1),
