(4730394, 681337, 44611, '<td valign="top">A really interesting scene.  Cropping a little tighter on the left would have got rid of the slightly distracting wall(?).  Wish it were a tad sharper too.</td>', 'A really interesting scene.  Cropping a little tighter on the left would have got rid of the slightly distracting wall(?).  Wish it were a tad sharper too.', '2008-05-28 14:59:08.000000', NULL, 1),
(4730396, 681872, 44611, '<td valign="top">Good concept with the paper boat - I like the colours of the boat very much.  Such a shame about the distracting foreground though.</td>', 'Good concept with the paper boat - I like the colours of the boat very much.  Such a shame about the distracting foreground though.', '2008-05-28 14:59:51.000000', NULL, 1),
(4730401, 682075, 44611, '<td valign="top">Lovely light and what a fantastic old boat.</td>', 'Lovely light and what a fantastic old boat.', '2008-05-28 15:02:34.000000', NULL, 1),
(4730402, 682189, 44611, '<td valign="top">Terrific reflection.</td>', 'Terrific reflection.', '2008-05-28 15:04:28.000000', NULL, 1),
(4730406, 680049, 93883, '<td valign="top">I like the angle you caught the boat at, but the background with the biker and comforting park like setting really works against the drama of the turn.   Also, it may have worked better if the sailboat were further from  land so that the trees didn''t take up so much of the image and cut off the tip of the sail.</td>', 'I like the angle you caught the boat at, but the background with the biker and comforting park like setting really works against the drama of the turn.   Also, it may have worked better if the sailboat were further from  land so that the trees didn''t take up so much of the image and cut off the tip of the sail.', '2008-05-28 15:06:28.000000', NULL, 1),
(4730412, 681770, 30982, '<td valign="top">Love the way the sun is caught in the corner of the window!  I like the bigger to smaller lineup as well.  Not as fond of the rock in the background, but I don''t suppose you could move it.  :-)</td>', 'Love the way the sun is caught in the corner of the window!  I like the bigger to smaller lineup as well.  Not as fond of the rock in the background, but I don''t suppose you could move it.  :-)', '2008-05-28 15:09:02.000000', NULL, 1),
(4730418, 682050, 30982, '<td valign="top">Lovely day for a regatta, it looks like!  I really like the color of the reflections in the water and the sunlight on the two smaller craft, but there appears to be a bit of overprocessing as it appears on my monitor.  There''s a glowy halo above the treeline that seems unnatural.  You''ve got some dust bunnies showing in the sky - you can indeed clone or heal those away if you wish.</td>', 'Lovely day for a regatta, it looks like!  I really like the color of the reflections in the water and the sunlight on the two smaller craft, but there appears to be a bit of overprocessing as it appears on my monitor.  There''s a glowy halo above the treeline that seems unnatural.  You''ve got some dust bunnies showing in the sky - you can indeed clone or heal those away if you wish.', '2008-05-28 15:10:31.000000', NULL, 1),
(4730420, 681636, 44611, '<td valign="top">Love the colours and the different approach.</td>', 'Love the colours and the different approach.', '2008-05-28 15:11:15.000000', NULL, 1),
(4730421, 682072, 30982, '<td valign="top">Bold color study.  Do kayaks really have corks in ''em?  Something about the top of the image seems just a tad off to me, but it''s not a major detractor.</td>', 'Bold color study.  Do kayaks really have corks in ''em?  Something about the top of the image seems just a tad off to me, but it''s not a major detractor.', '2008-05-28 15:11:23.000000', NULL, 1),
(4730422, 682003, 30982, '<td valign="top">Very nice warm light to this - I like the gold on the water.  The boat is kind of a quiet surprise - slowly appears after one takes in the sky and the water.</td>', 'Very nice warm light to this - I like the gold on the water.  The boat is kind of a quiet surprise - slowly appears after one takes in the sky and the water.', '2008-05-28 15:12:11.000000', NULL, 1),
(4730424, 680150, 93883, '<td valign="top">I really enjoy the colors in this, and especially how the sky fades to dark.  But right now the tip of the boat almost draws your eye straight out of the picture.  Maybe if the whispy cloud in the top left were stronger it would help draw the eye back in.</td>', 'I really enjoy the colors in this, and especially how the sky fades to dark.  But right now the tip of the boat almost draws your eye straight out of the picture.  Maybe if the whispy cloud in the top left were stronger it would help draw the eye back in.', '2008-05-28 15:12:45.000000', NULL, 1),
(4730425, 681783, 30982, '<td valign="top">I like the composition and the toning, but the processing - probably added blur - almost makes this seem a bit miniaturized and feel just a touch unreal.  The shot is well taken.</td>', 'I like the composition and the toning, but the processing - probably added blur - almost makes this seem a bit miniaturized and feel just a touch unreal.  The shot is well taken.', '2008-05-28 15:13:11.000000', NULL, 1),
(4730427, 681091, 93883, '<td valign="top">Great use of sepia!</td>', 'Great use of sepia!', '2008-05-28 15:13:37.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4730428, 681633, 30982, '<td valign="top">Lovely vessel and I like the warm light - looks like it may have been evening?</td>', 'Lovely vessel and I like the warm light - looks like it may have been evening?', '2008-05-28 15:13:38.000000', NULL, 1),
(4730430, 682097, 30982, '<td valign="top">Great ue of curves and a dramatic sky.</td>', 'Great ue of curves and a dramatic sky.', '2008-05-28 15:13:52.000000', NULL, 1),
(4730434, 682031, 30982, '<td valign="top">The threatening sky quite nearly gives this movement.  Excellent detail.  This may be very monitor dependent - some may find it too dark, but the gradations here are very good.</td>', 'The threatening sky quite nearly gives this movement.  Excellent detail.  This may be very monitor dependent - some may find it too dark, but the gradations here are very good.', '2008-05-28 15:15:19.000000', NULL, 1),
(4730436, 682190, 30982, '<td valign="top">Stunning convergences of the dock and the clouds.  Well chosen to present in B&amp;W.</td>', 'Stunning convergences of the dock and the clouds.  Well chosen to present in B&W.', '2008-05-28 15:15:54.000000', NULL, 1),
(4730437, 681566, 44611, '<td valign="top">Love the idea here and the colours, although I think the colour could have a bit more ''pop''.  Wish the horizontal was straight and that the front of the lower canoes wasn''t cropped off.</td>', 'Love the idea here and the colours, although I think the colour could have a bit more ''pop''.  Wish the horizontal was straight and that the front of the lower canoes wasn''t cropped off.', '2008-05-28 15:16:04.000000', NULL, 1),
(4730438, 682185, 30982, '<td valign="top">Great idea for this challenge!  Like the warmth of the expressions and the why you''ve isolated them in the light.</td>', 'Great idea for this challenge!  Like the warmth of the expressions and the why you''ve isolated them in the light.', '2008-05-28 15:16:18.000000', NULL, 1),
(4730439, 681996, 93883, '<td valign="top">Light, colors, lines, they all create interest here.  A good abstraction.</td>', 'Light, colors, lines, they all create interest here.  A good abstraction.', '2008-05-28 15:16:31.000000', NULL, 1),
(4730442, 681251, 30982, '<td valign="top">Heh - the initial focal point here seems to be bird leavings.  Looks like this one has seen better days.</td>', 'Heh - the initial focal point here seems to be bird leavings.  Looks like this one has seen better days.', '2008-05-28 15:16:50.000000', NULL, 1),
(4730444, 681406, 30982, '<td valign="top">Nicely minimal and gray.</td>', 'Nicely minimal and gray.', '2008-05-28 15:17:15.000000', NULL, 1),
(4730445, 682115, 30982, '<td valign="top">And it''s an admirable job for a boat out of water.  Nice rich color.</td>', 'And it''s an admirable job for a boat out of water.  Nice rich color.', '2008-05-28 15:17:37.000000', NULL, 1),
(4730447, 681733, 93883, '<td valign="top">oohhh, this one made me shiver my timbers. So corny yes, but I couldn''t help it :)</td>', 'oohhh, this one made me shiver my timbers. So corny yes, but I couldn''t help it :)', '2008-05-28 15:18:51.000000', NULL, 1),
(4730449, 681223, 44611, '<td valign="top">Sky is just fabulous - boat is rather overpowered!</td>', 'Sky is just fabulous - boat is rather overpowered!', '2008-05-28 15:20:07.000000', NULL, 1),
(4730450, 682190, 93883, '<td valign="top">I little busy, but a great tonal range and I love how oppressive the sky is.</td>', 'I little busy, but a great tonal range and I love how oppressive the sky is.', '2008-05-28 15:20:35.000000', NULL, 1),
(4730455, 682192, 93883, '<td valign="top">Very cute scene, I wish that branch weren''t coming out of her head though.</td>', 'Very cute scene, I wish that branch weren''t coming out of her head though.', '2008-05-28 15:22:45.000000', NULL, 1),
(4730459, 681689, 30982, '<td valign="top">This is pretty good for a "toy" shot.  Nice creation you''ve come up with here.</td>', 'This is pretty good for a "toy" shot.  Nice creation you''ve come up with here.', '2008-05-28 15:23:57.000000', NULL, 1),
(4730461, 681967, 30982, '<td valign="top">Very serene - seems almost unreal it''s so perfect!</td>', 'Very serene - seems almost unreal it''s so perfect!', '2008-05-28 15:24:21.000000', NULL, 1),
(4730462, 682097, 93883, '<td valign="top">Wish the blue tones were a little more separated.  Nice angle and composition though.</td>', 'Wish the blue tones were a little more separated.  Nice angle and composition though.', '2008-05-28 15:24:31.000000', NULL, 1),
(4730465, 681062, 93883, '<td valign="top">Wo ai Shanghai! (I love Shanghai!)</td>', 'Wo ai Shanghai! (I love Shanghai!)', '2008-05-28 15:26:08.000000', NULL, 1),
(4730466, 682176, 30982, '<td valign="top">Chaos at the boat docks?  A good peek into what is probably a regatta of sorts.  The composition seems just a bit off to me - maybe a bit too crowded?  Can''t quite put my finger on it.</td>', 'Chaos at the boat docks?  A good peek into what is probably a regatta of sorts.  The composition seems just a bit off to me - maybe a bit too crowded?  Can''t quite put my finger on it.', '2008-05-28 15:26:11.000000', NULL, 1),
(4730468, 681786, 30982, '<td valign="top">Lovely wood on the forward boat.  This is a tad oversharpened to my eye, but nice rich color.</td>', 'Lovely wood on the forward boat.  This is a tad oversharpened to my eye, but nice rich color.', '2008-05-28 15:26:50.000000', NULL, 1),
(4730471, 682128, 30982, '<td valign="top">Wonderful rich green color in the water - looks almost like an oil painting.  The boat kinda looks like a folded paper cup more than a boat, though.</td>', 'Wonderful rich green color in the water - looks almost like an oil painting.  The boat kinda looks like a folded paper cup more than a boat, though.', '2008-05-28 15:28:01.000000', NULL, 1),
(4730475, 681736, 30982, '<td valign="top">I think the desat works wonderfully for this, and I love how the smoke from the stack is so well isolated from the sky.  This is a very nice presentation.</td>', 'I think the desat works wonderfully for this, and I love how the smoke from the stack is so well isolated from the sky.  This is a very nice presentation.', '2008-05-28 15:28:56.000000', NULL, 1),
(4730480, 682141, 30982, '<td valign="top">I like just the barest touch of blue in the water of the wake.</td>', 'I like just the barest touch of blue in the water of the wake.', '2008-05-28 15:30:59.000000', NULL, 1),
(4730481, 682195, 93883, '<td valign="top">I love the reflection of the water against the boat and the range of blues.</td>', 'I love the reflection of the water against the boat and the range of blues.', '2008-05-28 15:32:39.000000', NULL, 1),
(4730483, 681503, 30982, '<td valign="top">I like the differences amidst the similarity.</td>', 'I like the differences amidst the similarity.', '2008-05-28 15:32:58.000000', NULL, 1),
(4730487, 681819, 30982, '<td valign="top">Has a neat south Florida pastel-ish kinda thing going on.  Great sky, cool bird.</td>', 'Has a neat south Florida pastel-ish kinda thing going on.  Great sky, cool bird.', '2008-05-28 15:33:39.000000', NULL, 1),
(4730490, 681103, 93883, '<td valign="top">It looks like some camera shake is hurting this one a bit.</td>', 'It looks like some camera shake is hurting this one a bit.', '2008-05-28 15:33:59.000000', NULL, 1),
(4730491, 680049, 30982, '<td valign="top">Life is better (something) together - nice sentiment.</td>', 'Life is better (something) together - nice sentiment.', '2008-05-28 15:34:04.000000', NULL, 1),
(4730495, 681812, 30982, '<td valign="top">I''ll wager this is shot underwater, looking up?  Quite a nifty view!</td>', 'I''ll wager this is shot underwater, looking up?  Quite a nifty view!', '2008-05-28 15:35:01.000000', NULL, 1),
(4730497, 682098, 30982, '<td valign="top">Awesome perspective, great shot - love the wake left by the boat passing - like a lane in the water.  I also really like the contrast of the cool colors of the water/boat/ice contrasted with the warmth of the land and the lighthouse.</td>', 'Awesome perspective, great shot - love the wake left by the boat passing - like a lane in the water.  I also really like the contrast of the cool colors of the water/boat/ice contrasted with the warmth of the land and the lighthouse.', '2008-05-28 15:36:02.000000', NULL, 1),
(4730520, 680438, 93883, '<td valign="top">This is quite busy.  Putting it in black and white might allow the geometry of it to take center stage.</td>', 'This is quite busy.  Putting it in black and white might allow the geometry of it to take center stage.', '2008-05-28 15:42:38.000000', NULL, 1),
(4730569, 681984, 811, '<td valign="top">I like the minimalistic feeling of this .</td>', 'I like the minimalistic feeling of this .', '2008-05-28 15:59:49.000000', NULL, 1),
(4730601, 682093, 811, '<td valign="top">It appears to be oversharpened, just a hair.</td>', 'It appears to be oversharpened, just a hair.', '2008-05-28 16:14:22.000000', NULL, 1),
(4730608, 680905, 3569, '<td valign="top">wonderful sharpness, dof, facial experssions and shot.</td>', 'wonderful sharpness, dof, facial experssions and shot.', '2008-05-28 16:16:53.000000', NULL, 1),
(4730609, 680742, 3569, '<td valign="top">great shot</td>', 'great shot', '2008-05-28 16:18:09.000000', NULL, 1),
(4730611, 682086, 3569, '<td valign="top">a few rocks hugh.  A bit of water would help your score.</td>', 'a few rocks hugh.  A bit of water would help your score.', '2008-05-28 16:18:42.000000', NULL, 1),
(4730612, 681657, 3569, '<td valign="top">nice shot</td>', 'nice shot', '2008-05-28 16:19:40.000000', NULL, 1),
(4730631, 681400, 30982, '<td valign="top">Wonderful wisps of clouds.  Where are all the people?  Looks like a place like this would make for nice family gatherings.</td>', 'Wonderful wisps of clouds.  Where are all the people?  Looks like a place like this would make for nice family gatherings.', '2008-05-28 16:27:39.000000', NULL, 1),
(4730633, 682075, 30982, '<td valign="top">Great angle, wonderful deep DOF.</td>', 'Great angle, wonderful deep DOF.', '2008-05-28 16:28:25.000000', NULL, 1),
(4730634, 681807, 30982, '<td valign="top">I can see this in a travel magazine.  Well composed, great color.</td>', 'I can see this in a travel magazine.  Well composed, great color.', '2008-05-28 16:28:50.000000', NULL, 1),
(4730641, 681976, 30982, '<td valign="top">Very nice of the clouds to form such a lovely framing!  Great detail on the hull.</td>', 'Very nice of the clouds to form such a lovely framing!  Great detail on the hull.', '2008-05-28 16:30:27.000000', NULL, 1),
(4730645, 682161, 30982, '<td valign="top">What a warm and inviting view.  Oddly enough, I quite like the smokestack - lends a solidness to the shot.  Great time of day for this.</td>', 'What a warm and inviting view.  Oddly enough, I quite like the smokestack - lends a solidness to the shot.  Great time of day for this.', '2008-05-28 16:31:01.000000', NULL, 1),
(4730647, 682003, 811, '<td valign="top">A bit over saturated and it feels like it is tilted to the left.</td>', 'A bit over saturated and it feels like it is tilted to the left.', '2008-05-28 16:31:21.000000', NULL, 1),
(4730650, 681970, 30982, '<td valign="top">I think I just saw this boat.  Another very good shot of it, by the way.</td>', 'I think I just saw this boat.  Another very good shot of it, by the way.', '2008-05-28 16:31:31.000000', NULL, 1),
(4730651, 681733, 30982, '<td valign="top">Very nice light to show off the rigging and the deck on this detailed model.</td>', 'Very nice light to show off the rigging and the deck on this detailed model.', '2008-05-28 16:31:56.000000', NULL, 1),
(4730669, 680905, 30982, '<td valign="top">Great action shot - excellent color, clarity, and some fun expressions!</td>', 'Great action shot - excellent color, clarity, and some fun expressions!', '2008-05-28 16:41:33.000000', NULL, 1),
(4730671, 681337, 30982, '<td valign="top">I really like this - has a little of everythng and yet still features the boat quite clearly.</td>', 'I really like this - has a little of everythng and yet still features the boat quite clearly.', '2008-05-28 16:41:55.000000', NULL, 1),
(4730673, 681410, 30982, '<td valign="top">I have no idea how you did this, but it''s quite awesome.</td>', 'I have no idea how you did this, but it''s quite awesome.', '2008-05-28 16:42:21.000000', NULL, 1),
(4730675, 681511, 30982, '<td valign="top">Perfectly titled and incredibly well seen.  Nicely done.</td>', 'Perfectly titled and incredibly well seen.  Nicely done.', '2008-05-28 16:42:47.000000', NULL, 1),
(4730677, 682171, 30982, '<td valign="top">Magical and gorgeous!</td>', 'Magical and gorgeous!', '2008-05-28 16:43:23.000000', NULL, 1),
(4730683, 681984, 30982, '<td valign="top">Excellent minimal, high keyish kinda thing.  Love the starkness and retained detail.</td>', 'Excellent minimal, high keyish kinda thing.  Love the starkness and retained detail.', '2008-05-28 16:48:15.000000', NULL, 1),
(4730730, 681719, 90658, '<td valign="top">Not technically a boat, but a boat part so I''m giving you credit :)<br/> <br/>Angles, angles, angles.  Everything is on the horizontal.  Did you take any where the axle bar was at the 45?  Giving the illusion of the wheel coming up from the bottom corner rather than shooting in from the left.  I''m talking about the black bar.<br/> <br/>Colors work well together, though.</td>', 'Not technically a boat, but a boat part so I''m giving you credit :) Angles, angles, angles.  Everything is on the horizontal.  Did you take any where the axle bar was at the 45?  Giving the illusion of the wheel coming up from the bottom corner rather than shooting in from the left.  I''m talking about the black bar. Colors work well together, though.', '2008-05-28 17:21:50.000000', NULL, 1),
(4730732, 682092, 63503, '<td valign="top">It is good to have another dpchallenger in town!! I saw you on Sunday about 3 or 4 pm shooting pictures from the Blue Heron Bridge, that was when my brother and I arrived to shoot ours. Talk about a small world !!</td>', 'It is good to have another dpchallenger in town!! I saw you on Sunday about 3 or 4 pm shooting pictures from the Blue Heron Bridge, that was when my brother and I arrived to shoot ours. Talk about a small world !!', '2008-05-28 17:22:50.000000', NULL, 1),
(4730733, 682028, 90658, '<td valign="top">Seems too dark for me.  From the monitor I''m looking at, I just see a splotch of red.  Only when I turn down the lights and look at my monitor from an angle other than straight on, do I see the paper boat.</td>', 'Seems too dark for me.  From the monitor I''m looking at, I just see a splotch of red.  Only when I turn down the lights and look at my monitor from an angle other than straight on, do I see the paper boat.', '2008-05-28 17:23:20.000000', NULL, 1),
(4730745, 681282, 90658, '<td valign="top">Oddly, the first thing I see is the flag, then the green sail covering.</td>', 'Oddly, the first thing I see is the flag, then the green sail covering.', '2008-05-28 17:29:09.000000', NULL, 1),
(4730750, 680473, 90658, '<td valign="top">The darkness of the sky processing obscures the mast and sail lines of the boat.  I think the fact that the boat is on dry land is infinitely more important than the clouds.  What would this look like in color?  Would the boat be more visible?</td>', 'The darkness of the sky processing obscures the mast and sail lines of the boat.  I think the fact that the boat is on dry land is infinitely more important than the clouds.  What would this look like in color?  Would the boat be more visible?', '2008-05-28 17:30:50.000000', NULL, 1),
(4730755, 682050, 90658, '<td valign="top">For me the processing is over done and the colors don''t seem natural...the hulls, people and shore line.  So if that was where you were going...yoohoo! :)</td>', 'For me the processing is over done and the colors don''t seem natural...the hulls, people and shore line.  So if that was where you were going...yoohoo! :)', '2008-05-28 17:32:02.000000', NULL, 1),
(4730756, 681816, 90658, '<td valign="top">I really like the aspects of this.  Was there any way to lighten the color of the water, even just slightly.  I think the "beat up" aspect of the boats is sort of lost against a backdrop that is darker than the "scars."</td>', 'I really like the aspects of this.  Was there any way to lighten the color of the water, even just slightly.  I think the "beat up" aspect of the boats is sort of lost against a backdrop that is darker than the "scars."', '2008-05-28 17:33:25.000000', NULL, 1),
(4730757, 681511, 90658, '<td valign="top">Yes, it is unexpected.  Not technically a boat, just a part of one, I still think you did well and met the challenge.</td>', 'Yes, it is unexpected.  Not technically a boat, just a part of one, I still think you did well and met the challenge.', '2008-05-28 17:34:33.000000', NULL, 1),
(4730759, 680487, 90658, '<td valign="top">The whites seem blown out to me.  If you attempting a ghost-like image, I think a gussian blur or some backlighting would have been better.</td>', 'The whites seem blown out to me.  If you attempting a ghost-like image, I think a gussian blur or some backlighting would have been better.', '2008-05-28 17:35:52.000000', NULL, 1),
(4730770, 681984, 90658, '<td valign="top">Judging by the title, you meant to blow out the water and make this look like a negative image.  These types of shots do absolutely nothing for me.  Art speaks differently to different people.<br/> <br/>I do like that you attempted something different.  Watch the focus problems, things get a little wonky around the heads of the people in the boat...might be a processing issue too.</td>', 'Judging by the title, you meant to blow out the water and make this look like a negative image.  These types of shots do absolutely nothing for me.  Art speaks differently to different people. I do like that you attempted something different.  Watch the focus problems, things get a little wonky around the heads of the people in the boat...might be a processing issue too.', '2008-05-28 17:45:54.000000', NULL, 1),
(4730777, 682190, 90658, '<td valign="top">Too dark for my tastes.  Sometimes the beauty of a storm cloud is more impressive when left alone.  I almost get the feeling that you took a picture on a nice day and processed it to this point.  The boats are completely obscured and not really an element due to the darkness of the clouds and the deck in the foreground.</td>', 'Too dark for my tastes.  Sometimes the beauty of a storm cloud is more impressive when left alone.  I almost get the feeling that you took a picture on a nice day and processed it to this point.  The boats are completely obscured and not really an element due to the darkness of the clouds and the deck in the foreground.', '2008-05-28 17:47:47.000000', NULL, 1),
(4730785, 681811, 90658, '<td valign="top">Interesting choice in removing all color except that found on the boat.  The shot seems out of balance to me.  I''m wondering if it is the angle...having the majority of the boat on the right or the fact that 60% of the noticable color is bunched up on the right.  Something seems off to me.</td>', 'Interesting choice in removing all color except that found on the boat.  The shot seems out of balance to me.  I''m wondering if it is the angle...having the majority of the boat on the right or the fact that 60% of the noticable color is bunched up on the right.  Something seems off to me.', '2008-05-28 17:50:19.000000', NULL, 1),
(4730789, 682171, 90658, '<td valign="top">This is sort of interesting to look at.  Sort of impressionistic.  I''m still attempting to figure out how you did this.  Is this a reflection turned upside down?</td>', 'This is sort of interesting to look at.  Sort of impressionistic.  I''m still attempting to figure out how you did this.  Is this a reflection turned upside down?', '2008-05-28 17:51:35.000000', NULL, 1),
(4730794, 680417, 90658, '<td valign="top">Sort of seems snap-shottish.  Albeit, a really good one.  Sort of the thing that you would expect to see in a company sales brochure.  "Why our shipping company is better than someone else''s?</td>', 'Sort of seems snap-shottish.  Albeit, a really good one.  Sort of the thing that you would expect to see in a company sales brochure.  "Why our shipping company is better than someone else''s?', '2008-05-28 17:53:02.000000', NULL, 1),
(4730808, 682075, 90658, '<td valign="top">This is interesting.  I like what you''ve done, but I feel like you''ve gone just a smidge too far in the processing.  There is a sense of two shots converged into one, for me.  If you look around the rope and scroll line, there is a ghost line between the boat and the sky.  Almost like a bad "green screen effect" in really early sci-fi movies.</td>', 'This is interesting.  I like what you''ve done, but I feel like you''ve gone just a smidge too far in the processing.  There is a sense of two shots converged into one, for me.  If you look around the rope and scroll line, there is a ghost line between the boat and the sky.  Almost like a bad "green screen effect" in really early sci-fi movies.', '2008-05-28 17:58:08.000000', NULL, 1),
(4730809, 682064, 90658, '<td valign="top">Generally, I don''t like these processing effects, but you have found the perfect balance between interest and craziness.  Nice job.</td>', 'Generally, I don''t like these processing effects, but you have found the perfect balance between interest and craziness.  Nice job.', '2008-05-28 17:59:26.000000', NULL, 1),
(4730811, 682084, 90658, '<td valign="top">Stunning colors.  Nicely done!</td>', 'Stunning colors.  Nicely done!', '2008-05-28 18:01:06.000000', NULL, 1),
(4730817, 682097, 90658, '<td valign="top">Blues are nice.  Coloring is nice.  I like the attention to the cropping details...the bottom of the blue stripe just hits the bottom corner of the shot, as the railing does the same in the upper corner.  These things make viewing a picture of any quality a pleasure...and the quality of this one is wonderful.  Thank you.</td>', 'Blues are nice.  Coloring is nice.  I like the attention to the cropping details...the bottom of the blue stripe just hits the bottom corner of the shot, as the railing does the same in the upper corner.  These things make viewing a picture of any quality a pleasure...and the quality of this one is wonderful.  Thank you.', '2008-05-28 18:03:29.000000', NULL, 1),
(4730823, 681806, 90658, '<td valign="top">The sky and background is so blown out that it is distracting to me.  I''d bet that was your intent, though. :)</td>', 'The sky and background is so blown out that it is distracting to me.  I''d bet that was your intent, though. :)', '2008-05-28 18:04:32.000000', NULL, 1),
(4730832, 681638, 90658, '<td valign="top">My only advise would be to crop in more on the left to lose some of the background clutter and bring the focal point more into center.  With 2 boats, you could get away with it because there would still be visiual interest to the right foreground and the left background.</td>', 'My only advise would be to crop in more on the left to lose some of the background clutter and bring the focal point more into center.  With 2 boats, you could get away with it because there would still be visiual interest to the right foreground and the left background.', '2008-05-28 18:06:51.000000', NULL, 1),
(4730838, 682177, 90658, '<td valign="top">With all of the browns in the water, dock &amp; rust that bright blue rope is out of place.  This is advanced editing, I''m sure you could have done something to "fix" that.  :)</td>', 'With all of the browns in the water, dock & rust that bright blue rope is out of place.  This is advanced editing, I''m sure you could have done something to "fix" that.  :)', '2008-05-28 18:09:01.000000', NULL, 1),
(4730840, 682022, 90658, '<td valign="top">Peaceful shot.  Honestly, I wish that you could have found a bird flying through, then brilliance!  :)  I know, you can''t just wish for a bird and have one come winging through in exactly the spot you want it.</td>', 'Peaceful shot.  Honestly, I wish that you could have found a bird flying through, then brilliance!  :)  I know, you can''t just wish for a bird and have one come winging through in exactly the spot you want it.', '2008-05-28 18:10:16.000000', NULL, 1),
(4730844, 681406, 90658, '<td valign="top">Nicely done!  Very appropriate.</td>', 'Nicely done!  Very appropriate.', '2008-05-28 18:10:24.000000', NULL, 1),
(4730845, 682023, 90658, '<td valign="top">Interesting effect.  You have really gone outside of the box by using a model ship and by creating the illusion of sailing.  I would prefer a slight more cropping on the left, just to complete the composition.</td>', 'Interesting effect.  You have really gone outside of the box by using a model ship and by creating the illusion of sailing.  I would prefer a slight more cropping on the left, just to complete the composition.', '2008-05-28 18:10:27.000000', NULL, 1),
