(4734247, 681546, 92864, '<td valign="top">I find the slightly tilted shoreline a bit distracting.</td>', 'I find the slightly tilted shoreline a bit distracting.', '2008-05-30 08:45:50.000000', NULL, 1),
(4734254, 681994, 92864, '<td valign="top">The sky looks blown-out...</td>', 'The sky looks blown-out...', '2008-05-30 08:48:27.000000', NULL, 1),
