(4735387, 682196, 83313, '<td valign="top">A lot of people are going to ding this as out of focus, but in combination with the backlighting, I think it gives this something of an impressionistic feel.</td>', 'A lot of people are going to ding this as out of focus, but in combination with the backlighting, I think it gives this something of an impressionistic feel.', '2008-05-30 23:32:47.000000', NULL, 1),
(4735397, 681806, 83313, '<td valign="top">The tone of the boat''s hull seems a bit lighter in the center, which looks out of place, but other than that nitpick, I like this.</td>', 'The tone of the boat''s hull seems a bit lighter in the center, which looks out of place, but other than that nitpick, I like this.', '2008-05-30 23:36:28.000000', NULL, 1),
(4735406, 681990, 83313, '<td valign="top">I have almost no idea what I am looking at here. Offhand it looks like someone in the shower, with a paper boat on their head. Or, it could be a sailboat coming into a cave. Maybe. I''m going to consider it a semi-abstract. It is an interesting composition, however.</td>', 'I have almost no idea what I am looking at here. Offhand it looks like someone in the shower, with a paper boat on their head. Or, it could be a sailboat coming into a cave. Maybe. I''m going to consider it a semi-abstract. It is an interesting composition, however.', '2008-05-30 23:40:10.000000', NULL, 1),
(4735408, 682022, 83313, '<td valign="top">Niccccee! Bold and simple. Very smooth tones on that sky. Good job on that.</td>', 'Niccccee! Bold and simple. Very smooth tones on that sky. Good job on that.', '2008-05-30 23:41:07.000000', NULL, 1),
(4735413, 682110, 83313, '<td valign="top">A little sexual innuendo? "It''s not the size of the mast that matters..."?</td>', 'A little sexual innuendo? "It''s not the size of the mast that matters..."?', '2008-05-30 23:42:35.000000', NULL, 1),
(4735416, 682017, 83313, '<td valign="top">I like this but there is a bit of a shadow or secondary image showing.</td>', 'I like this but there is a bit of a shadow or secondary image showing.', '2008-05-30 23:44:13.000000', NULL, 1),
(4735419, 681613, 83313, '<td valign="top">Good perspective, though I don''t think the sepia works for such a modern looking boat.</td>', 'Good perspective, though I don''t think the sepia works for such a modern looking boat.', '2008-05-30 23:45:11.000000', NULL, 1),
(4735420, 682098, 30669, '<td valign="top">Newfoundland?  I like this shot a lot.</td>', 'Newfoundland?  I like this shot a lot.', '2008-05-30 23:45:18.000000', NULL, 1),
(4735424, 682031, 83313, '<td valign="top">Overall, I like this, my nitpicks are a bit too dark and the silo behind it looks at first glance like it may be on the ship.</td>', 'Overall, I like this, my nitpicks are a bit too dark and the silo behind it looks at first glance like it may be on the ship.', '2008-05-30 23:47:06.000000', NULL, 1),
(4735431, 681223, 83313, '<td valign="top">Hope you can pronounce that first place! Awesome clouds, and I like the way they loom over the ship that looks tiny in relation.</td>', 'Hope you can pronounce that first place! Awesome clouds, and I like the way they loom over the ship that looks tiny in relation.', '2008-05-30 23:49:08.000000', NULL, 1),
(4735432, 681251, 83313, '<td valign="top">I''d have cloned out the bird poop.</td>', 'I''d have cloned out the bird poop.', '2008-05-30 23:49:44.000000', NULL, 1),
(4735435, 682097, 83313, '<td valign="top">Nice and bold.</td>', 'Nice and bold.', '2008-05-30 23:50:16.000000', NULL, 1),
(4735437, 681639, 83313, '<td valign="top">This was the kind of shot I was trying to get for this challenge, but there was not a single sailboat on the lake that day. good job.</td>', 'This was the kind of shot I was trying to get for this challenge, but there was not a single sailboat on the lake that day. good job.', '2008-05-30 23:51:45.000000', NULL, 1),
(4735442, 681103, 83313, '<td valign="top">Looks like you have some blur from a slow shutter speed. I''m afraid that hurts it quite a bit.</td>', 'Looks like you have some blur from a slow shutter speed. I''m afraid that hurts it quite a bit.', '2008-05-30 23:53:19.000000', NULL, 1),
(4735445, 680473, 83313, '<td valign="top">I know this will do well!</td>', 'I know this will do well!', '2008-05-30 23:53:51.000000', NULL, 1),
(4735450, 682106, 83313, '<td valign="top">What a nice place to stay. Buoy, oh buoy!</td>', 'What a nice place to stay. Buoy, oh buoy!', '2008-05-30 23:55:49.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4735455, 681546, 83313, '<td valign="top">Nice, starting to get a little banding around the sun, but these kind of shots are tough with that aspect.</td>', 'Nice, starting to get a little banding around the sun, but these kind of shots are tough with that aspect.', '2008-05-30 23:57:01.000000', NULL, 1),
(4735457, 681819, 83313, '<td valign="top">The processing gives this a bit of a look that I have done with some of mine, but I don''t find it works well with this particular scene.</td>', 'The processing gives this a bit of a look that I have done with some of mine, but I don''t find it works well with this particular scene.', '2008-05-30 23:58:13.000000', NULL, 1),
(4735459, 682174, 83313, '<td valign="top">Hope floats? Could have used that in "movie titles". My wife and I still argue about that movie. She loved it, but I say that hope sank.</td>', 'Hope floats? Could have used that in "movie titles". My wife and I still argue about that movie. She loved it, but I say that hope sank.', '2008-05-30 23:59:31.000000', NULL, 1),
(4735461, 681630, 83313, '<td valign="top">A good view, though I think the comp could benefit form cropping a little more off the right side.</td>', 'A good view, though I think the comp could benefit form cropping a little more off the right side.', '2008-05-31 00:00:44.000000', NULL, 1),
(4735462, 681400, 83313, '<td valign="top">Wait for me!</td>', 'Wait for me!', '2008-05-31 00:01:11.000000', NULL, 1),
(4735463, 681967, 83313, '<td valign="top">I think this will place highly, but I do see some jaggies on the top edges of the boats. Try a different resizing method that can give a smoother looking result.</td>', 'I think this will place highly, but I do see some jaggies on the top edges of the boats. Try a different resizing method that can give a smoother looking result.', '2008-05-31 00:02:54.000000', NULL, 1),
(4735467, 681511, 83313, '<td valign="top">A nice eye for catching this perspective.</td>', 'A nice eye for catching this perspective.', '2008-05-31 00:05:13.000000', NULL, 1),
(4735470, 682030, 30669, '<td valign="top">iceland???   Beautiful !    10</td>', 'iceland???   Beautiful !    10', '2008-05-31 00:05:19.000000', NULL, 1),
(4735472, 681140, 83313, '<td valign="top">I can''t give a low vote to a lego boat. I wouldn''t be able to sleep. Nice out of the box thinking.</td>', 'I can''t give a low vote to a lego boat. I wouldn''t be able to sleep. Nice out of the box thinking.', '2008-05-31 00:06:43.000000', NULL, 1),
(4735475, 681633, 77724, '<td valign="top">Focus &amp; Exposure spot on. While the tight crop does work I like to see how this looks with a little more water in from of the boat.</td>', 'Focus & Exposure spot on. While the tight crop does work I like to see how this looks with a little more water in from of the boat.', '2008-05-31 00:12:11.000000', NULL, 1),
(4735477, 682064, 77724, '<td valign="top">Nice composition.  The processing makes this look like an old painting and is not to my taste.</td>', 'Nice composition.  The processing makes this look like an old painting and is not to my taste.', '2008-05-31 00:13:35.000000', NULL, 1),
(4735497, 682064, 94153, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2008-05-31 00:25:48.000000', NULL, 1),
(4735501, 681216, 77724, '<td valign="top">White balane is off - looks like incandenent shot at a daylight setting - still a nice night scene.</td>', 'White balane is off - looks like incandenent shot at a daylight setting - still a nice night scene.', '2008-05-31 00:27:03.000000', NULL, 1),
(4735503, 682182, 94153, '<td valign="top">I love this photo!</td>', 'I love this photo!', '2008-05-31 00:27:48.000000', NULL, 1),
(4735510, 682192, 94153, '<td valign="top">What a great picture!  It reminds me of a scene of the childhood story Peter Pan.</td>', 'What a great picture!  It reminds me of a scene of the childhood story Peter Pan.', '2008-05-31 00:30:15.000000', NULL, 1),
(4735511, 681372, 77724, '<td valign="top">Nice textures.  I think the guy should either be in focus or out of the frame</td>', 'Nice textures.  I think the guy should either be in focus or out of the frame', '2008-05-31 00:30:20.000000', NULL, 1),
(4735513, 681967, 94153, '<td valign="top">Wow! beautiful!</td>', 'Wow! beautiful!', '2008-05-31 00:30:49.000000', NULL, 1),
(4735559, 682075, 94152, '<td valign="top">This looks to me like subtle and clarifying use of HDR. Excellent photo.</td>', 'This looks to me like subtle and clarifying use of HDR. Excellent photo.', '2008-05-31 00:57:03.000000', NULL, 1),
(4735567, 682087, 77724, '<td valign="top">The goose makes the shot</td>', 'The goose makes the shot', '2008-05-31 01:00:15.000000', NULL, 1),
(4735579, 681337, 77724, '<td valign="top">Nice slice of life composition,</td>', 'Nice slice of life composition,', '2008-05-31 01:05:00.000000', NULL, 1),
(4735591, 681744, 76430, '<td valign="top">I love the reflections here, but they kind of mask out the boat making it harder to see.  I am also not a fan of very narrow pictures.  It is nice and sharp.  What is that line going from the engine to the tile, an antenna?  At any rate, I''m not voting in this challenge since I''m participating.</td>', 'I love the reflections here, but they kind of mask out the boat making it harder to see.  I am also not a fan of very narrow pictures.  It is nice and sharp.  What is that line going from the engine to the tile, an antenna?  At any rate, I''m not voting in this challenge since I''m participating.', '2008-05-31 01:19:42.000000', NULL, 1),
(4735593, 681770, 77724, '<td valign="top">Well done for a backlit scene.  I like how you caught the sun comming through the windows.</td>', 'Well done for a backlit scene.  I like how you caught the sun comming through the windows.', '2008-05-31 01:23:09.000000', NULL, 1),
(4735597, 682186, 77724, '<td valign="top">Excellent clarity, nice colors.</td>', 'Excellent clarity, nice colors.', '2008-05-31 01:24:12.000000', NULL, 1),
(4735609, 681685, 76335, '<td valign="top">Colors are dull. It needs more contrast.</td>', 'Colors are dull. It needs more contrast.', '2008-05-31 01:38:01.000000', NULL, 1),
(4735612, 681785, 76335, '<td valign="top">Wow, what''s up with that background? Very interesting processing.</td>', 'Wow, what''s up with that background? Very interesting processing.', '2008-05-31 01:38:38.000000', NULL, 1),
(4735614, 681984, 76335, '<td valign="top">Very artistic and original. Nice job!</td>', 'Very artistic and original. Nice job!', '2008-05-31 01:39:25.000000', NULL, 1),
(4735617, 681986, 76335, '<td valign="top">But how seaworthy is it?</td>', 'But how seaworthy is it?', '2008-05-31 01:40:04.000000', NULL, 1),
(4735654, 681973, 77724, '<td valign="top">The boat looks OK, but the background seems kind of dull.</td>', 'The boat looks OK, but the background seems kind of dull.', '2008-05-31 01:55:49.000000', NULL, 1),
(4735656, 681806, 77724, '<td valign="top">Backlighting very well done here.</td>', 'Backlighting very well done here.', '2008-05-31 01:56:16.000000', NULL, 1),
(4735673, 681812, 77724, '<td valign="top">I''ve commented on every other image in this challenge and have saved this one for last.  It simply fascinates me.  <br/> <br/>At first glance it looks like a toy in a swimming pool, but then I notice the trees and a lamp post? in the reflection suggesting a real boat.  If it is real, how to achieve the effect  a fisheye looking down?  But then how to keep yourself out of the frame.  <br/> <br/>Further review I notice WB seems different on the from &amp; back of the boat, auggesting mixed light and a toy of some sort.  <br/> <br/>Then theres the title  Upside Down adds to the puzzlement.  <br/> <br/>An overhead shot of a boat with mixed WB and looks like it could be a toy would not get a good score from me.  The reflections keep me coming back again and again.  Anything that makes the viewer spend time on it deserves high marks.  Well done.  I just hope the speed voters just blow past this without giving it due consideration.</td>', 'I''ve commented on every other image in this challenge and have saved this one for last.  It simply fascinates me.   At first glance it looks like a toy in a swimming pool, but then I notice the trees and a lamp post? in the reflection suggesting a real boat.  If it is real, how to achieve the effect  a fisheye looking down?  But then how to keep yourself out of the frame.   Further review I notice WB seems different on the from & back of the boat, auggesting mixed light and a toy of some sort.   Then theres the title  Upside Down adds to the puzzlement.   An overhead shot of a boat with mixed WB and looks like it could be a toy would not get a good score from me.  The reflections keep me coming back again and again.  Anything that makes the viewer spend time on it deserves high marks.  Well done.  I just hope the speed voters just blow past this without giving it due consideration.', '2008-05-31 02:08:38.000000', NULL, 1),
(4735677, 682022, 77724, '<td valign="top">Love this - Awsome color in a great capture.  Bumping up - 10.</td>', 'Love this - Awsome color in a great capture.  Bumping up - 10.', '2008-05-31 02:10:15.000000', NULL, 1),
(4735678, 681967, 77724, '<td valign="top">Wish I knew how to make water look like that. Bumping up.</td>', 'Wish I knew how to make water look like that. Bumping up.', '2008-05-31 02:10:30.000000', NULL, 1),
(4735679, 681976, 77724, '<td valign="top">Love the poit of view, awsome colors, terrific sharpness really brings out the texture.  Very well done.  Bumping Up.</td>', 'Love the poit of view, awsome colors, terrific sharpness really brings out the texture.  Very well done.  Bumping Up.', '2008-05-31 02:10:38.000000', NULL, 1),
(4735680, 682123, 77724, '<td valign="top">Very cool effect, nice take on this challenge.  Bumping Up</td>', 'Very cool effect, nice take on this challenge.  Bumping Up', '2008-05-31 02:10:49.000000', NULL, 1),
