(4735753, 682098, 76430, '<td valign="top">Iceland?  Beautiful shot, good boat trail with a lighthouse and a nice iceberg making it a difficult photo to get.</td>', 'Iceland?  Beautiful shot, good boat trail with a lighthouse and a nice iceberg making it a difficult photo to get.', '2008-05-31 03:07:03.000000', NULL, 1),
(4735755, 682190, 76430, '<td valign="top">Excellent clarity and good contrast.</td>', 'Excellent clarity and good contrast.', '2008-05-31 03:08:29.000000', NULL, 1),
